import { homeView, mountExperience, propertyGallery } from './experience.js';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = { user: null, demo: true, saved: new Set(), sector: 'residential', content: {}, routeToken: 0, editor: null, gallery: null, pending: null, authMode: 'login', threadFilter: 'all' };
const paths = {arrow:'M4 12h16m-6-6 6 6-6 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',search:'m21 21-5-5M19 10.5a8.5 8.5 0 1 1-17 0 8.5 8.5 0 0 1 17 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bed:'M3 18v3m18-3v3M3 12V5h18v7M2 18v-6h20v6ZM6 12V8h5v4m2 0V8h5v4',bath:'M3 12h18v3a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5Zm2 8-1 2m15-2 1 2M5 12V5a3 3 0 0 1 6 0',car:'m3 10 2-6h14l2 6M2 10h20v8H2Zm2 8v3m16-3v3M6 14h1m10 0h1',close:'m6 6 12 12M18 6 6 18',filter:'M4 7h16M4 17h16M8 4v6m8 4v6',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',message:'M21 3H3v14h5l4 4 4-4h5ZM7 8h10M7 12h6',calendar:'M4 5h16v16H4ZM8 2v6m8-6v6M4 10h16',home:'m3 10 9-8 9 8M5 8v13h14V8M9 21v-8h6v8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',back:'M20 12H4m6-6-6 6 6 6',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',logout:'M9 3H3v18h6m5-14 5 5-5 5M8 12h12'};
const icon = name => `<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.arrow}"/></svg>`;
const money = p => new Intl.NumberFormat('en-AU', {style:'currency',currency:p.currency||'AUD',maximumFractionDigits:0}).format(p.price_minor / 100);
const price = p => p.price_label ? esc(p.price_label) : money(p);
const residentialTypes = [['house','House'],['apartment','Apartment'],['townhouse','Townhouse'],['villa','Villa'],['land','Land']];
const commercialTypes = [['office','Offices'],['retail','Retail'],['industrial','Industrial / Warehouse'],['hotel','Hotel / Leisure'],['medical','Medical / Consulting'],['showroom','Showrooms / Bulky goods'],['development_land','Development / Land'],['rural','Rural / Agriculture'],['other','Other']];
const typeLabels = Object.fromEntries([...residentialTypes, ...commercialTypes]);
const typeLabel = p => typeLabels[p?.property_type] || esc(p?.property_type || '');
const saleMethodLabels = {private_sale:'Private sale',expressions_of_interest:'Expressions of interest',auction:'Auction',tender:'Tender',price_on_application:'Price on application'};
const saleMethodLabel = p => saleMethodLabels[p?.sale_method] || saleMethodLabels.private_sale;
const saleMethodPhrases = {private_sale:'Private sale',expressions_of_interest:'Sale by expressions of interest',auction:'Auction',tender:'Tender',price_on_application:'Price on application'};
const saleMethodPhrase = p => saleMethodPhrases[p?.sale_method] || saleMethodPhrases.private_sale;
const tenancyLabels = {vacant:'Vacant possession',leased:'Leased investment',owner_occupied:'Owner occupied'};
const isNew = iso => !!iso && (Date.now() - new Date(iso).getTime()) <= 14*24*60*60*1000;
const daysAgo = iso => Math.max(0, Math.floor((Date.now() - new Date(iso).getTime())/86400000));
const listedLine = p => p.listed_at ? (isNew(p.listed_at) ? 'New listing' : `Listed ${daysAgo(p.listed_at)} day${daysAgo(p.listed_at)===1?'':'s'} ago`) : '';
const statusName = s => ({under_offer:'Under offer',application_pending:'Application pending',available:'Available',sold:'Sold',leased:'Leased',withdrawn:'Withdrawn',requested:'Requested',confirmed:'Confirmed',completed:'Completed',cancelled:'Cancelled'})[s] || s;
const date = value => value ? new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date(value)) : '';
const areaFacts = p => { const rows = []; if (p.floor_area) rows.push(`${p.floor_area.toLocaleString('en-AU')} m² floor`); if (p.land_area) rows.push(`${p.land_area.toLocaleString('en-AU')} m² land`); if (p.parking) rows.push(`${p.parking} car${p.parking === 1 ? '' : 's'}`); if (p.tenancy && tenancyLabels[p.tenancy]) rows.push(tenancyLabels[p.tenancy]); if (!rows.length) { const pairs = (p.details || []).filter(d => Array.isArray(d) && d.length === 2 && (d[0] + d[1]).length <= 36).slice(0, 3); rows.push(...pairs.map(([l, v]) => `${l}: ${v}`)); } return rows.length ? `<div class="facts">${rows.map(r => `<span>${icon('pin')}${esc(r)}</span>`).join('')}</div>` : ''; };
const facts = (p, max = 3) => { if ((p.sector || 'residential') === 'commercial') return areaFacts(p); if (p.property_type === 'land') { const pairs = (p.details || []).filter(d => Array.isArray(d) && d.length === 2); const short = pairs.filter(([l, v]) => (l + v).length <= 36); const rows = (short.length >= Math.min(max, pairs.length) ? short : pairs).slice(0, max); return rows.length ? `<div class="facts">${rows.map(([label,value]) => `<span>${icon('pin')}${esc(label)}: ${esc(value)}</span>`).join('')}</div>` : ''; } return `<div class="facts"><span>${icon('bed')}${p.bedrooms === 0 ? 'Studio' : `${p.bedrooms} beds`}</span><span>${icon('bath')}${p.bathrooms} bath${p.bathrooms===1?'':'s'}</span><span>${icon('car')}${p.parking} car${p.parking===1?'':'s'}</span></div>`; };
const img = (p, cls = '', eager = false) => `<img class="${cls}" src="${esc(p.media?.[0]?.url || '/assets/courtyard.webp')}" alt="${esc(p.media?.[0]?.alt || (p.is_demo===false ? p.title : `${p.title}, fictional concept home`))}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="1024" height="688">`;
const badge = s => `<span class="tag ${s === 'available' || s === 'confirmed' ? 'green' : ['sold','leased','cancelled'].includes(s)?'clay':''}">${esc(statusName(s))}</span>`;
const statusBadges = (p, leading = '') => { const rows = []; if (leading) rows.push(leading); if (p.featured && p.is_demo === false) rows.push('<span class="tag highlight">Highlight</span>'); if (p.is_demo === false && isNew(p.listed_at)) rows.push('<span class="tag green">New</span>'); if (p.transaction_status !== 'available') rows.push(badge(p.transaction_status)); else if (p.price_label) rows.push('<span class="tag">Price on request</span>'); return rows.join(''); };
async function api(path, options = {}) { const res = await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body === undefined ? undefined : JSON.stringify(options.body)});const data = await res.json();if(!res.ok)throw Object.assign(new Error(data.error || 'Please try again.'),{status:res.status});return data; }
const post = (path, body = {}) => api(path,{method:'POST',body});
function toast(message) {$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function empty(title,copy,link='/properties?sector=residential',label='Browse homes') {return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p>${link?`<a class="btn secondary" href="${esc(link)}">${esc(label)} ${icon('arrow')}</a>`:''}</div>`;}
function renderHeader() {const path=location.pathname;const q=new URLSearchParams(location.search);$('#header').innerHTML=`<div class="wrap"><nav class="nav" aria-label="Main navigation"><a class="wordmark" href="/" aria-label="Porli home">porli</a><div class="nav-links"><a class="${path==='/properties'&&q.get('sector')!=='commercial'?'active':''}" href="/properties?sector=residential">Residential</a><a class="${path==='/properties'&&q.get('sector')==='commercial'?'active':''}" href="/properties?sector=commercial">Commercial</a><a class="about-link" href="/about">How Porli works</a></div><div class="nav-end"><a class="save-nav" href="/account/saved" aria-label="Saved homes">${icon('heart')}<span>Saved${state.saved.size?` (${state.saved.size})`:''}</span></a>${state.user?`<a class="btn secondary" href="${isStaff()?'/admin':'/account/messages'}">${esc(state.user.name.split(' ')[0])} ${icon('user')}</a>`:'<button class="btn secondary" data-action="auth">Sign in</button>'}</div></nav></div><div class="demo-strip">Porli concept · Includes fictional homes with generated imagery · Headline listing photographs supplied by the property</div>`;
$('#footer').innerHTML=`<div class="wrap rule"><div class="footer-top"><div><a class="wordmark" href="/">porli</a><p>Find your next place.</p></div><div class="footer-links"><div><a href="/properties?sector=residential">Residential</a><a href="/properties?sector=commercial">Commercial</a><a href="/account/saved">Saved homes</a></div><div><a href="/about">How Porli works</a><a href="/contact">Contact</a><a href="/admin">Team workspace</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Porli concept. Except where a listing states otherwise, homes are fictional.</span><span><a href="/privacy">Privacy</a> &nbsp; · &nbsp; <a href="/terms">Terms</a> &nbsp; · &nbsp; AUD / Australia–Sydney</span></div></div>`;}
const isStaff = () => ['staff','admin'].includes(state.user?.role);
function card(p) {const typeTag=`<span class="tag">${typeLabel(p)}</span>`;const saleLine=((p.sector||'residential')==='commercial'&&p.sale_method&&p.sale_method!=='private_sale')?`<div class="sale-method-line">${esc(saleMethodLabel(p))}</div>`:'';return `<article class="property-card reveal"><div class="card-image"><a href="/properties/${esc(p.slug)}">${img(p)}</a><div class="card-badges">${statusBadges(p,typeTag)}</div><button class="save-button ${state.saved.has(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.has(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${state.saved.has(p.id)}">${icon('heart')}</button></div><div class="card-body"><div class="card-location">${esc(p.locality)} · ${typeLabel(p)}</div><div class="card-title"><h3><a href="/properties/${esc(p.slug)}">${esc(p.title)}</a></h3><span class="price">${price(p)}</span></div>${saleLine}${facts(p,2)}<div class="card-demo">${p.is_demo===false?esc(listedLine(p)||'Listed recently'):'Fictional listing · Generated image'}</div></div></article>`;}
async function home() {const {properties}=await api('/properties?sector=all');return homeView({properties,state,esc,icon,money,price,card,empty,statusBadges,typeLabel});}
function options(values,current,placeholder) {return `${placeholder?`<option value="">${placeholder}</option>`:''}${values.map(([v,label])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(label)}</option>`).join('')}`;}
async function marketplace() {const q=new URLSearchParams(location.search);if(!q.has('sector'))q.set('sector','residential');const sector=q.get('sector');const {properties,total}=await api('/properties?'+q);const typeOptions=sector==='commercial'?commercialTypes:residentialTypes;return `<div class="wrap"><div class="page-top"><div class="eyebrow">The marketplace</div><h1>${sector==='commercial'?'Commercial property.':'Residential property.'}</h1><form class="search-bar" data-form="search"><div class="switch"><a class="${sector==='residential'?'selected':''}" href="/properties?sector=residential${q.get('location')?'&location='+encodeURIComponent(q.get('location')):''}">Residential</a><a class="${sector==='commercial'?'selected':''}" href="/properties?sector=commercial${q.get('location')?'&location='+encodeURIComponent(q.get('location')):''}">Commercial</a></div><label class="search-input">${icon('search')}<input name="location" aria-label="Search location" value="${esc(q.get('location'))}" placeholder="Suburb or property name"><button class="btn" aria-label="Search">${icon('arrow')}</button></label><button type="button" class="btn secondary" data-action="filters" aria-label="Filters" aria-expanded="${q.get('filters')==='1'}">${icon('filter')}<span>Filters</span></button></form>${q.get('filters')==='1'?`<form class="filters" data-form="filters"><label>${sector==='commercial'?'Category':'Property type'}<select name="type">${options(typeOptions,q.get('type'),sector==='commercial'?'All categories':'All types')}</select></label>${sector==='commercial'?`<label>Tenancy<select name="tenancy">${options([['vacant','Vacant possession'],['leased','Leased investment'],['owner_occupied','Owner occupied']],q.get('tenancy'),'Any')}</select></label><label>Minimum floor area (m²)<input type="number" min="0" name="min_floor" value="${esc(q.get('min_floor'))}" placeholder="No minimum"></label>`:`<label>Bedrooms<select name="beds">${options([['0','Studio'],['1','1+ bedrooms'],['2','2+ bedrooms'],['3','3+ bedrooms'],['4','4+ bedrooms']],q.get('beds'),'Any')}</select></label><label>Bathrooms<select name="baths">${options([['1','1+ bathrooms'],['2','2+ bathrooms'],['3','3+ bathrooms']],q.get('baths'),'Any')}</select></label>`}<label>Min price (AUD)<input type="number" min="0" name="min" value="${esc(q.get('min'))}" placeholder="No minimum"></label><label>Max price (AUD)<input type="number" min="0" name="max" value="${esc(q.get('max'))}" placeholder="No maximum"></label><label class="flex"><input type="checkbox" name="pending" value="1" ${q.get('pending')==='1'?'checked':''}>Include under offer</label><div class="filter-actions"><a href="/properties?sector=${sector}">Reset filters</a><button class="btn">Apply filters ${icon('check')}</button></div></form>`:''}</div><div class="chips">${['location','type','beds','baths','tenancy','min_floor','min','max','pending'].filter(k=>q.has(k)).map(k=>{const next=new URLSearchParams(q);next.delete(k);return `<a href="/properties?${esc(next)}" aria-label="Remove ${k} filter">${esc(k)}: ${esc(q.get(k))} &nbsp; ×</a>`;}).join('')}</div><div class="results-head"><span>${total} ${total===1?'property':'properties'} ${properties.some(p=>p.is_demo!==false)?'<span class="muted">· includes fictional concept listings</span>':''}</span><label><span class="sr-only">Sort properties</span><select data-change="sort" aria-label="Sort properties">${options([['newest','Newest first'],['price-asc','Price: low to high'],['price-desc','Price: high to low']],q.get('sort')||'newest')}</select></label></div>${properties.length?`<div class="cards listing-grid">${properties.map(card).join('')}</div>`:empty('No properties match these filters.','Try a different location or widen your price range.',`/properties?sector=${sector}`,'Reset filters')}</div>`;}
async function detail(slug) {const {property:p,slots}=await api('/properties/'+slug);state.currentProperty=p;state.currentSlots=slots;document.title=p.title+' — Porli';const real=p.is_demo===false;const sector=p.sector||'residential';const commercial=sector==='commercial';const hotel=p.property_type==='hotel';const highlightsLabel=commercial?'Investment highlights':'Highlights';let details=p.details||[];if(commercial&&p.zoning&&!details.some(([label])=>String(label).toLowerCase()==='zoning'))details=[...details,['Zoning',p.zoning]];const highlights=p.highlights||[];const description=String(p.description||'');const paragraphs=description.split(/\n\s*\n/).filter(Boolean).map(para=>`<p>${esc(para)}</p>`).join('');const long=description.length>600;let other=[];try{const all=(await api('/properties?sector=all')).properties.filter(o=>o.id!==p.id);const same=all.filter(o=>(o.sector||'residential')===sector);other=(same.length>=3?same:all).slice(0,3);}catch(e){}return `<div class="wrap"><div class="page-top"><div class="breadcrumb"><a href="/properties?sector=${sector}">${commercial?'Commercial property':'Residential property'}</a>${icon('arrow')}<span>${esc(p.locality)}</span></div><div class="detail-top"><div><div class="eyebrow">${typeLabel(p)} · ${esc(p.locality)}</div><h1>${esc(p.title)}</h1><p>${esc(p.locality)}${real?'':' · Fictional location'} &nbsp; ${badge(p.transaction_status)}${p.publication_state!=='published'?` &nbsp; ${badge(p.publication_state)}`:''}</p>${highlights.length?`<div class="eyebrow highlights-label">${highlightsLabel}</div><div class="chip-row">${highlights.slice(0,6).map(h=>`<span class="chip">${esc(h)}</span>`).join('')}</div>`:''}</div><div class="flex"><div><span class="price">${price(p)}</span><span class="sale-method-line small muted">${esc(saleMethodPhrase(p))}</span>${p.listed_at&&p.is_demo===false?`<span class="listed-line small muted">${esc(listedLine(p))}</span>`:''}</div><button class="icon-btn" data-action="save" data-id="${p.id}" aria-label="Save ${esc(p.title)}" aria-pressed="${state.saved.has(p.id)}">${icon('heart')}</button></div></div></div>${propertyGallery({p,img,esc,icon})}<p class="small muted">${real?'Photographs supplied by the property.':'Generated architectural study. This home, its location and price are fictional.'}</p><div class="detail-layout"><div class="detail-main">${facts(p)}<h2>About this property</h2><div class="prose-block${long?' is-collapsed':''}">${paragraphs}</div>${long?`<button type="button" class="link read-more-toggle" data-action="read-more">Read more ${icon('down')}</button>`:''}${details.length?`<h2>Property details</h2><table class="details-table"><tbody>${details.map(([label,value])=>`<tr><th>${esc(label)}</th><td>${esc(value)}</td></tr>`).join('')}</tbody></table>`:''}${p.features?.length?`<h2>Features</h2><ul class="features">${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}<h2>Around the property</h2><p>${real?'Only the locality is shown. Ask the team for the exact address.':`${esc(p.locality)} is a fictional location used for this concept. Only the locality is displayed; an exact address is not available.`}</p><h2>${hotel?'Viewing appointments':'Inspections'}</h2><p>${p.transaction_status==='available'?(hotel?'Request a viewing time. The team will confirm your appointment in your account.':'Request a time to visit. The team will confirm your inspection in your account.'):'This property is currently '+esc(statusName(p.transaction_status).toLowerCase())+'. Existing conversations remain available in your account.'}</p>${p.transaction_status==='available'?`<button class="link" data-action="inspect">${hotel?'Request a viewing':'Request an inspection'} ${icon('arrow')}</button>`:''}</div><aside class="contact-card"><div class="eyebrow">Property enquiries</div><h3>Ask the Porli team</h3><p>Ask a question about this ${hotel?'property':'home'} or request ${hotel?'a viewing':'an inspection'}. Your replies and booking updates stay in your account.</p>${p.transaction_status==='available'&&p.publication_state==='published'?`<button class="btn" data-action="enquire">Enquire about this property ${icon('message')}</button><button class="btn secondary" data-action="inspect">${hotel?'Request a viewing':'Request an inspection'} ${icon('calendar')}</button>`:`<p>${p.publication_state==='published'?'This home is not accepting new enquiries.':'Private staff preview. This listing is not public.'}</p>`}<div class="team-person"><div class="avatar">P</div><div><strong>Porli team</strong><span>Property enquiries</span></div></div></aside></div>${other.length?`<section class="more-properties" data-reveal><div class="section-head"><h2>Explore other properties</h2></div><div class="cards">${other.map(card).join('')}</div></section>`:''}</div>`;}
function sidebar(admin) {const items=admin?[['/admin','Overview','grid'],['/admin/properties','Properties','home'],['/admin/conversations','Shared inbox','message'],['/admin/inspections','Inspections','calendar'],['/admin/contacts','Contacts','user'],...(state.user.role==='admin'?[['/admin/content','Site content','grid'],['/admin/settings','Team access','user']]:[])]:[['/account/saved','Saved homes','heart'],['/account/messages','Messages','message'],['/account/inspections','Inspections','calendar'],['/account/settings','Your account','user']];return `<aside class="side-nav"><div class="eyebrow">${admin?'Team workspace':'Your place'}</div>${items.map(([url,label,i])=>`<a class="${location.pathname===url||(url!=='/admin'&&location.pathname.startsWith(url+'/'))?'active':''}" href="${url}">${icon(i)}${label}</a>`).join('')}${isStaff()?`<a href="${admin?'/account/saved':'/admin'}">${icon('arrow')}${admin?'Personal account':'Team workspace'}</a>`:''}<button class="link signout" data-action="logout">${icon('logout')}Sign out</button></aside>`;}
const heading=(title,subtitle='',action='')=>`<div class="workspace-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;
async function workspace() {const admin=location.pathname.startsWith('/admin');if(!state.user)return `<div class="wrap section">${empty('Your place starts here.','Sign in to save homes, keep conversations together and manage inspections.','', '')}<div class="flex"><button class="btn" data-action="auth">Sign in or create an account ${icon('arrow')}</button></div></div>`;if(admin&&!isStaff())return `<div class="wrap section">${empty('This space is for the team.','Your saved homes, messages and inspections are in your account.','/account/saved','Go to your account')}</div>`;let content='';const path=location.pathname;
  if(path==='/account/saved'){const{properties}=await api('/properties?saved=1');content=heading('Your shortlist.','The places you keep coming back to.')+(properties.length?`<div class="cards">${properties.map(card).join('')}</div>`:empty('A little room for possibilities.','Tap the heart on a home to keep it here.'));}
  else if(path==='/account/settings'){content=heading('Your account.','Your details, in one place.')+`<form data-form="profile" class="stack profile-form"><label>Your name<input name="name" value="${esc(state.user.name)}" required maxlength="80"></label><label>Email<input value="${esc(state.user.email)}" disabled></label><p class="small">Email verification and password recovery are not configured in this local concept.</p><div class="form-error" role="alert"></div><button class="btn">Save changes</button></form>`;}
  else if(path==='/admin') content=await dashboard();
  else if(path==='/admin/properties') content=await inventory();
  else if(path.startsWith('/admin/properties/')) content=await editor(path.split('/')[3]);
  else if(path.startsWith('/account/messages')||path.startsWith('/admin/conversations'))content=await inbox(admin);
  else if(path.endsWith('/inspections'))content=await inspections(admin);
  else if(path==='/admin/contacts'){const{conversations}=await api('/conversations');const contacts=[...new Map(conversations.map(c=>[c.customer.id,c.customer])).values()];content=heading('Contacts.','Contacts are created from property enquiries.')+(contacts.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Property conversations</th></tr></thead><tbody>${contacts.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.email)}</td><td>${conversations.filter(t=>t.customer.id===c.id).length}</td></tr>`).join('')}</tbody></table></div>`:empty('No enquiries yet.','People will appear here once they start a conversation.','',''));}
  else if(path==='/admin/content'&&state.user.role==='admin'){content=heading('Homepage content.','Edit the homepage headline and supporting copy.')+`<form class="stack profile-form" data-form="content"><label>Headline<input name="headline" value="${esc(state.content.headline)}" maxlength="80" required></label><label>Supporting copy<textarea name="intro" maxlength="200" required>${esc(state.content.intro)}</textarea></label><div class="form-error" role="alert"></div><button class="btn">Save homepage copy</button></form>`;}
  else if(path==='/admin/settings'&&state.user.role==='admin')content=await team();
  else content=empty('Page not found.','Choose a destination from the navigation.','/','Back to Porli');
  return `<div class="wrap workspace">${sidebar(admin)}<section class="workspace-body">${content}</section></div>`;
}
async function dashboard(){const days=new URLSearchParams(location.search).get('days')||'30';const d=await api('/admin/dashboard?days='+days);return heading('Team overview.','Local demo activity · all records are fictional.',`<select data-change="days" aria-label="Reporting period">${options([['7','Last 7 days'],['30','Last 30 days'],['90','Last 90 days']],days)}</select>`)+`<div class="stats">${[[d.live,'Available homes','Current','/admin/properties'],[d.awaiting,'Awaiting a reply','Current','/admin/conversations?filter=awaiting'],[d.new_conversations,'New conversations',`Last ${d.days} days`,'/admin/conversations'],[d.inspection_requests,'Inspection requests',`Last ${d.days} days`,'/admin/inspections'],[d.people,'Interested people',`Last ${d.days} days`,'/admin/contacts'],[d.enquired,'Homes receiving enquiries',`Last ${d.days} days`,'/admin/conversations'],[d.outcomes,'Sold',`Last ${d.days} days`,'/admin/properties'],[d.overdue,'Overdue follow-ups','Current','/admin/conversations?filter=overdue']].map(([n,l,t,url])=>`<a class="stat" href="${url}"><span>${l}</span><strong>${n}</strong><small>${t} ${icon('arrow')}</small></a>`).join('')}</div><div class="section-head"><h3>Waiting for a conversation.</h3><a class="link" href="/admin/conversations">Open inbox ${icon('arrow')}</a></div>${d.queue.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Person</th><th>Property</th><th>Latest message</th><th></th></tr></thead><tbody>${d.queue.map(c=>`<tr><td>${esc(c.customer.name)}</td><td>${esc(c.property.title)}</td><td>${esc(c.messages.at(-1)?.body.slice(0,75))}</td><td><a class="link" href="/admin/conversations/${c.id}">Reply ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('You’re all caught up.','Customer messages that need a reply will appear here.','','')}`;}
async function inventory(){const{properties}=await api('/admin/properties');return heading('Properties.','Draft, publish and keep availability up to date.',`<a class="btn" href="/admin/properties/new">${icon('plus')}Add a home</a>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>Property</th><th>Price</th><th>Publication</th><th>Availability</th><th></th></tr></thead><tbody>${properties.map(p=>`<tr><td><div class="property-cell">${img(p,'thumb')}<div><strong>${esc(p.title)}</strong><br><span class="muted small">${esc(p.locality)}</span></div></div></td><td>${price(p)}</td><td>${badge(p.publication_state)}</td><td>${badge(p.transaction_status)}</td><td><a class="link" href="/admin/properties/${p.id}/edit">Edit ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`;}
async function editor(id){const p=id==='new'?{title:'',sector:'residential',property_type:'house',price_minor:0,price_label:'',currency:'AUD',is_demo:1,bedrooms:3,bathrooms:2,parking:1,locality:'',summary:'',description:'',publication_state:'draft',transaction_status:'available',sale_method:'private_sale',floor_area:0,land_area:0,zoning:'',tenancy:'',media:[],features:[],highlights:[],details:[],featured:0,listed_at:''}:(await api('/properties/'+id)).property;state.editor=structuredClone(p);const demoFlag=p.is_demo??1;const sector=p.sector||'residential';return heading(id==='new'?'Add a property.':'Edit property.','Fixed listing template · Changes are saved together.',p.id?`<a class="btn secondary" href="/properties/${esc(p.slug)}">Preview ${icon('arrow')}</a>`:'')+`<form data-form="editor"><div class="editor-section"><h3>The essentials</h3><div class="form-grid"><label class="span-two">Property title<input name="title" value="${esc(p.title)}" required maxlength="120"></label><label>Sector<select name="sector" data-change="editor-sector">${options([['residential','Residential'],['commercial','Commercial']],sector)}</select></label><label>${sector==='commercial'?'Category':'Property type'}<select name="property_type" id="property-type">${options(sector==='commercial'?commercialTypes:residentialTypes,p.property_type)}</select></label><label>Locality<input name="locality" value="${esc(p.locality)}" maxlength="120"></label><label>Currency<select name="currency">${options([['AUD','AUD'],['THB','THB'],['USD','USD']],p.currency||'AUD')}</select></label><label>Price (AUD)<input name="price" type="number" min="0" step=".01" value="${p.price_minor/100}"></label><label class="span-two">Price label (shown instead of the price, e.g. "Price to be confirmed")<input name="price_label" value="${esc(p.price_label||'')}" maxlength="60"></label><label>Bedrooms<input name="bedrooms" type="number" min="0" max="99" value="${p.bedrooms}"></label><label>Bathrooms<input name="bathrooms" type="number" min="0" max="99" value="${p.bathrooms}"></label><label>Car spaces<input name="parking" type="number" min="0" max="99" value="${p.parking}"></label><label>Sale method<select name="sale_method">${options([['private_sale','Private sale'],['expressions_of_interest','Expressions of interest'],['auction','Auction'],['tender','Tender'],['price_on_application','Price on application']],p.sale_method||'private_sale')}</select></label><label>Floor area (m²)<input name="floor_area" type="number" min="0" value="${p.floor_area||0}"></label><label>Land area (m²)<input name="land_area" type="number" min="0" value="${p.land_area||0}"></label><label>Zoning<input name="zoning" value="${esc(p.zoning||'')}" maxlength="80"></label><label>Tenancy<select name="tenancy">${options([['','Not stated'],['vacant','Vacant possession'],['leased','Leased investment'],['owner_occupied','Owner occupied']],p.tenancy||'')}</select></label><label class="flex span-two"><input type="checkbox" name="real_listing" ${demoFlag?'':'checked'}>This is a real listing (not fictional)</label></div></div><div class="editor-section"><h3>Tell the story</h3><div class="stack"><label>Short summary<input name="summary" value="${esc(p.summary)}" maxlength="200"></label><label>Description<textarea name="description" maxlength="10000">${esc(p.description)}</textarea></label><label>Features (one per line)<textarea name="features">${esc((p.features||[]).join('\n'))}</textarea></label><label>Highlights (one per line, up to 6, shown as chips)<textarea name="highlights">${esc((p.highlights||[]).join('\n'))}</textarea></label><label>Property details (one per line, as "Label: value")<textarea name="details">${esc((p.details||[]).map(([label,value])=>`${label}: ${value}`).join('\n'))}</textarea></label></div></div><div class="editor-section"><h3>Photographs</h3><p class="small">First image is the cover. New publications require three distinct photographs. PNG, JPEG or WebP, up to 5 MB each.</p><label>Upload photographs<input type="file" accept="image/png,image/jpeg,image/webp" multiple data-change="upload"></label><div class="media-editor" id="media-editor">${mediaRows()}</div></div><div class="editor-section"><h3>Publication & availability</h3><div class="form-grid"><label>Publication<select name="publication_state">${options([['draft','Draft'],['published','Published'],['archived','Archived']],p.publication_state)}</select></label><label>Availability<select name="transaction_status" id="transaction-status">${statusOptions(p.transaction_status)}</select></label><label class="flex"><input type="checkbox" name="featured" ${p.featured?'checked':''}>Feature on homepage when available</label></div></div><div class="form-error" role="alert"></div><div class="editor-actions"><a class="btn secondary" href="/admin/properties">Cancel</a><button class="btn">Save listing ${icon('check')}</button></div></form>`;}
function statusOptions(current){return options(['available','under_offer','sold','withdrawn'].map(s=>[s,statusName(s)]),current);}
function mediaRows(){return state.editor.media.map((m,i)=>`<div class="media-row"><img src="${esc(m.url)}" alt="${esc(m.alt)}"><label>${i===0?'Cover image':'Image '+(i+1)}<input data-media-alt="${i}" value="${esc(m.alt)}" aria-label="Alternative text for image ${i+1}" maxlength="200"></label><div class="flex"><button type="button" class="icon-btn" data-action="media-up" ${i===0?'disabled':''} data-index="${i}" aria-label="Move image ${i+1} earlier">${icon('up')}</button><button type="button" class="icon-btn" data-action="media-down" ${i===state.editor.media.length-1?'disabled':''} data-index="${i}" aria-label="Move image ${i+1} later">${icon('down')}</button><button type="button" class="icon-btn" data-action="media-remove" data-index="${i}" aria-label="Remove image ${i+1}">${icon('close')}</button></div></div>`).join('');}
async function inbox(admin){const{conversations}=await api('/conversations');const q=new URLSearchParams(location.search),filter=q.get('filter')||'all';let list=conversations;if(filter==='awaiting')list=list.filter(c=>!c.blocked&&c.stage!=='closed'&&c.messages.at(-1)?.role==='customer');if(filter==='unread')list=list.filter(c=>c.unread);if(filter==='mine')list=list.filter(c=>c.assigned_to===state.user.id);if(filter==='overdue')list=list.filter(c=>c.stage!=='closed'&&c.due_at&&c.due_at<new Date().toISOString());const selected=conversations.find(c=>c.id===location.pathname.split('/')[3])||list[0];state.currentThread=selected;const base=admin?'/admin/conversations':'/account/messages';return heading(admin?'Shared inbox.':'Your conversations.',admin?'Questions, replies and next steps.':'Every home has its own conversation.',`<button class="btn secondary small" data-action="refresh">Refresh</button>`)+`${admin?`<label class="small">Show<select data-change="inbox-filter">${options([['all','All conversations'],['awaiting','Awaiting reply'],['unread','Unread'],['mine','Assigned to me'],['overdue','Overdue follow-ups']],filter)}</select></label><br>`:''}${list.length||selected?`<div class="inbox"><div class="thread-list">${list.map(c=>`<a class="thread-item ${selected?.id===c.id?'active':''}" href="${base}/${c.id}${filter!=='all'?'?filter='+filter:''}"><strong>${esc(admin?c.customer.name:c.property.title)} ${c.unread?`<span class="tag green">${c.unread} new</span>`:''}</strong><p>${esc(admin?c.property.title:c.property.locality)}</p><p>${esc(c.messages.at(-1)?.body.slice(0,90))}</p><span>${date(c.messages.at(-1)?.created_at)}</span></a>`).join('')||'<p class="small">No matching conversations.</p>'}</div><div class="thread-detail">${selected?await threadHTML(selected,admin):''}</div></div>`:empty('No conversations yet.','Ask about a property to start a conversation with the team.')}`;}
async function threadHTML(c,admin){await post(`/conversations/${c.id}/read`);let team=[];if(admin)team=(await api('/admin/team')).users.filter(u=>u.active&&['staff','admin'].includes(u.role));return `<div class="thread-heading"><div><h3>${esc(c.property.title)}</h3><p>${esc(admin?c.customer.name:c.property.locality)} · ${esc(statusName(c.property.transaction_status))}</p></div><a class="icon-btn" href="/properties/${esc(c.property.slug)}" aria-label="View property">${icon('arrow')}</a></div><div class="messages">${c.messages.map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}"><p>${esc(m.body)}</p><small>${esc(m.name)} · ${date(m.created_at)}</small></div>`).join('')}</div><form class="composer" data-form="reply"><label class="sr-only" for="reply-body">Your message</label><textarea id="reply-body" name="body" placeholder="Write your message…" required maxlength="5000">${esc(sessionStorage.getItem('draft-'+c.id)||'')}</textarea><div class="form-error" role="alert"></div><button class="btn">Send message ${icon('arrow')}</button><p class="small muted">Saved in this conversation. Email notifications are not configured.</p></form>${admin?`<details class="internal"><summary>Team notes & next steps · private</summary>${c.notes.map(n=>`<div class="note">${esc(n.body)}<br><small>${esc(n.name)} · ${date(n.created_at)}</small></div>`).join('')}<form data-form="note"><label>Internal note<textarea name="body" required placeholder="Only your team can read this." maxlength="5000"></textarea></label><div class="form-error" role="alert"></div><button class="btn secondary">Add internal note</button></form><form data-form="thread-workflow"><label>Stage<select name="stage">${options(['new','in_conversation','inspection','offer_application','closed'].map(s=>[s,s.replaceAll('_',' ')]),c.stage)}</select></label><label>Assigned to<select name="assigned_to">${options(team.map(u=>[u.id,u.name]),c.assigned_to,'Unassigned')}</select></label><label>Next action<input name="follow_up" value="${esc(c.follow_up)}" maxlength="300"></label><label>Due (your device time)<input name="due_at" type="datetime-local" value="${c.due_at?localInput(c.due_at):''}"></label><label class="flex"><input type="checkbox" name="blocked" ${c.blocked?'checked':''}>Block new customer messages</label><div class="form-error" role="alert"></div><button class="btn secondary">Save next steps</button></form></details>`:''}`;}
function localInput(value){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
async function inspections(admin){const{inspections:rows}=await api('/inspections');return heading(admin?'Inspections.':'Your inspections.','Times shown in Australia/Sydney. A request is not a confirmed booking.',admin?'<button class="btn" data-action="new-slot">Add inspection time</button>':'')+(rows.length?rows.map(i=>`<article class="inspection-card"><div><div class="eyebrow">${esc(i.name)}</div><h3>${esc(i.title)}</h3><p>${i.starts_at?date(i.starts_at)+' · Australia/Sydney':esc(i.proposed)}</p><p>${i.reason?esc(i.reason):''}</p>${i.transaction_status!=='available'&&i.status==='confirmed'?'<p class="error">Home no longer available. Please resolve this inspection.</p>':''}</div><div class="stack">${badge(i.status)}<div class="actions">${admin&&i.status==='requested'?`<button class="btn small" data-action="inspection-status" data-id="${i.id}" data-status="confirmed" data-property="${i.property_id}" data-slot="${i.slot_id||''}">Confirm</button>`:''}${admin&&i.status==='confirmed'?`<button class="btn small" data-action="inspection-status" data-id="${i.id}" data-status="completed">Complete</button>`:''}${['requested','confirmed'].includes(i.status)?`<button class="btn secondary small" data-action="inspection-status" data-id="${i.id}" data-status="cancelled">Cancel</button>`:''}</div></div></article>`).join(''):empty('Nothing in the diary yet.','Choose a home and request a time to take a closer look.'));}
async function team(){const{users}=await api('/admin/team');return heading('Team access.','Role changes end existing sessions. Your own access cannot be changed here.')+`<div class="stack">${users.map(u=>`<form data-form="team" class="inspection-card"><input type="hidden" name="id" value="${u.id}"><div><strong>${esc(u.name)}</strong><p class="small">${esc(u.email)}</p></div><div class="stack"><label>Role<select name="role" ${u.id===state.user.id?'disabled':''}>${options([['customer','Customer'],['staff','Staff'],['admin','Administrator']],u.role)}</select></label><label class="flex"><input type="checkbox" name="active" ${u.active?'checked':''} ${u.id===state.user.id?'disabled':''}>Active</label>${u.id!==state.user.id?'<button class="btn secondary small">Save access</button>':''}<div class="form-error" role="alert"></div></div></form>`).join('')}</div>`;}
function infoPage(path){const pages={about:['A property marketplace for buyers and investors.','Porli brings residential and commercial listings, property enquiries and inspection requests together. Browse available properties, compare the details and save a shortlist. When a property interests you, contact the team directly from its listing.','The Porli team creates and manages listings, replies to enquiries and confirms inspections. Customers can browse without an account; an account is required to save properties, send messages or request a viewing. This is a working concept. Except where a listing states otherwise, properties, locations and prices on this site are fictional, and their images were generated with Higgsfield.'],contact:['Let’s start with a home.','For questions about a property, open its listing and choose “Enquire about this property”. Your conversation stays with that home.','This is a local concept. There is no live agency telephone number, email service or physical office attached to it.'],privacy:['Your information, in this concept.','Accounts, saved properties, conversations and inspection requests are stored in a local database on this computer. Staff accounts can read property enquiries; private staff notes are restricted to the team.','Use fictional details while trying the concept. No email delivery or third-party analytics are configured. This is an implementation notice, not an approved production privacy policy. Operator details, retention rules and data-request procedures must be settled before public launch.'],terms:['A working concept.','Except where a listing states otherwise, properties, locations, prices and availability on this site are fictional. Images for fictional listings are generated architectural studies and do not represent actual properties offered for sale.','Inspection requests demonstrate the workflow and are not bookings for real properties. Production terms and the legal operator have not yet been finalised.']};const p=pages[path];return p?`<div class="wrap"><div class="page-top"><div class="eyebrow">Porli / ${esc(path)}</div><h1>${p[0]}</h1></div><div class="prose"><p>${p[1]}</p><p>${p[2]}</p><a class="btn" href="/properties?sector=residential">Explore the properties ${icon('arrow')}</a></div></div>`:`<div class="wrap section">${empty('This door doesn’t open here.','The page could not be found.','/','Back to Porli')}</div>`;}
async function render({scroll=true}={}) {const token=++state.routeToken;document.body.classList.toggle('edition-front',location.pathname==='/');renderHeader();$('#main').setAttribute('aria-busy','true');document.title='Porli — Find your next place';try {const p=location.pathname;let html;if(p==='/')html=await home();else if(p==='/properties')html=await marketplace();else if(p.startsWith('/properties/'))html=await detail(p.split('/')[2]);else if(p.startsWith('/account')||p.startsWith('/admin'))html=await workspace();else html=infoPage(p.slice(1));if(token!==state.routeToken)return;$('#main').innerHTML=html;$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');if(scroll)window.scrollTo(0,0);const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target);}}),{threshold:.12});$$('.scroll-reveal').forEach(el=>observer.observe(el));const messages=$('.messages');if(messages)messages.scrollTop=messages.scrollHeight;mountExperience();if(p.startsWith('/properties/')&&new URLSearchParams(location.search).get('enquire')==='1'){history.replaceState({},'',location.pathname);enquiry();}}catch(e){if(token===state.routeToken)$('#main').innerHTML=`<div class="wrap section">${empty(e.status===404?'This home isn’t available.':'Something needs another look.',e.message,'/properties?sector=residential','Browse homes')}<button class="btn secondary" data-action="refresh">Try again</button></div>`;}finally{if(token===state.routeToken)$('#main').removeAttribute('aria-busy');}}
function navigate(url,options={}){const next=new URL(url,location.origin);history.pushState({},'',next.pathname+next.search+next.hash);render(options);}
function closeModal(){const dialog=$('#modal');dialog.close();dialog.className='';}
function modal(title,body,cls=''){const dialog=$('#modal');dialog.className=cls;dialog.innerHTML=`<div class="modal-inner"><div class="modal-top"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</div>`;if(!dialog.open)dialog.showModal();}
function auth(pending){if(pending)state.pending=pending;const register=state.authMode==='register';modal(register?'Make yourself at home.':'Welcome back.',`<p>${register?'Save your favourites and keep the conversation going.':'Your shortlist, conversations and next steps.'}</p><div class="switch"><button class="${!register?'selected':''}" data-action="auth-mode" data-mode="login">Sign in</button><button class="${register?'selected':''}" data-action="auth-mode" data-mode="register">Create an account</button></div><form data-form="auth">${register?'<label>Your name<input name="name" autocomplete="name" required maxlength="80"></label>':''}<label>Email<input name="email" type="email" autocomplete="email" required maxlength="200"></label><label>Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="12"':''} required maxlength="256"></label>${register?'<p class="small">At least 12 characters. Please use fictional details for this local concept.</p>':''}<div class="form-error" role="alert"></div><button class="btn">${register?'Create account':'Sign in'} ${icon('arrow')}</button></form>${state.demo?`<div class="demo-auth"><div class="eyebrow">Try the local experience</div><div class="demo-accounts"><button class="btn secondary" data-action="demo-login" data-role="customer">Explore as a customer</button><button class="btn secondary" data-action="demo-login" data-role="admin">Open team workspace</button></div><p class="small muted">Demo accounts share fictional records on this computer.</p></div>`:''}`);}
async function signedIn(data,admin=false){state.user=data.user;state.saved=new Set((await api('/saves')).ids);closeModal();const pending=state.pending;state.pending=null;if(pending){renderHeader();mountExperience();await pending();}else if(admin)navigate('/admin');else await render({scroll:false});}
async function save(id){if(!state.user)return auth(()=>save(id));const saved=state.saved.has(id);await api('/saves',{method:saved?'DELETE':'POST',body:{property_id:id}});saved?state.saved.delete(id):state.saved.add(id);renderHeader();mountExperience();$$(`[data-action="save"][data-id="${id}"]`).forEach(b=>{b.classList.toggle('saved',!saved);b.setAttribute('aria-pressed',String(!saved));b.setAttribute('aria-label',b.getAttribute('aria-label').replace(/^(Save|Unsave)/,saved?'Save':'Unsave'));});toast(saved?'Removed from your shortlist.':'Saved to your shortlist.');if(location.pathname==='/account/saved')render({scroll:false});}
function enquiry(){if(!state.user)return auth(enquiry);const p=state.currentProperty;const draft=sessionStorage.getItem('enquiry-'+p.id);const prefill=draft!==null?draft:(p.is_demo===false?`I am interested in ${p.title}.`:'');modal('Ask about this place.',`<p>${esc(p.title)} · ${esc(p.locality)}</p><form data-form="enquiry"><label>Your message<textarea name="body" maxlength="5000" required placeholder="What would you like to know?">${esc(prefill)}</textarea></label><div class="form-error" role="alert"></div><button class="btn">Send to the team ${icon('arrow')}</button><p class="small">Your message will be saved in your account. No email is sent.</p></form>`);}
function inspect(){if(!state.user)return auth(inspect);const p=state.currentProperty;modal('Take a closer look.',`<p>${esc(p.title)} · Times in Australia/Sydney.</p><form data-form="inspection"><fieldset><legend>Choose a time</legend><div class="stack">${state.currentSlots.map(s=>`<label class="slot"><input type="radio" name="slot_id" value="${s.id}">${icon('calendar')}${date(s.starts_at)}</label>`).join('')}<label class="slot"><input type="radio" name="slot_id" value="" ${!state.currentSlots.length?'checked':''}>Suggest another time</label></div></fieldset><label>Alternative time or a note<input name="proposed" placeholder="e.g. Tuesday afternoon" maxlength="300"></label><p class="small">This is a request. The team will confirm the time in your account.</p><div class="form-error" role="alert"></div><button class="btn">Request inspection ${icon('arrow')}</button></form>`);}
function gallery(index=0){state.gallery=index;const p=state.currentProperty;const media=p.media[index];if(!media)return;const d=$('#modal');d.className='gallery-dialog';d.innerHTML=`<div class="modal-top"><h2 id="dialog-title">${esc(p.title)}</h2><button class="icon-btn" data-action="close" aria-label="Close gallery">${icon('close')}</button></div><img src="${esc(media.url)}" alt="${esc(media.alt)}"><div class="gallery-bottom"><span>${index+1} / ${p.media.length}${p.is_demo===false?'':' · Generated concept image'}</span><div class="flex">${p.media.length>1?`<button class="icon-btn" data-action="gallery-prev" aria-label="Previous image">${icon('back')}</button><button class="icon-btn" data-action="gallery-next" aria-label="Next image">${icon('arrow')}</button>`:''}</div></div>`;if(!d.open)d.showModal();}
async function slotModal(){const{properties}=await api('/admin/properties');modal('Make time for a visit.',`<form data-form="new-slot"><label>Property<select name="property_id">${options(properties.filter(p=>p.transaction_status==='available').map(p=>[p.id,p.title]))}</select></label><label>Date and time (your device time)<input type="datetime-local" name="starts_at" required></label><label>Capacity<input type="number" min="1" max="100" value="4" name="capacity" required></label><p class="small">Stored as UTC and displayed to customers in Australia/Sydney.</p><div class="form-error" role="alert"></div><button class="btn">Add inspection time</button></form>`);}
document.addEventListener('click',async event=>{const a=event.target.closest('a');if(a&&a.origin===location.origin&&!a.hasAttribute('download')&&a.target!=='_blank'&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&event.button===0){if(a.getAttribute('href')?.startsWith('#')){event.preventDefault();const target=document.getElementById(a.hash.slice(1));if(target){history.pushState({},'',a.hash);target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(a.hash==='#main')target.focus({preventScroll:true});}return;}event.preventDefault();navigate(a.href);return;}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;try{
 if(action==='auth')auth();if(action==='auth-mode'){state.authMode=button.dataset.mode;auth();}if(action==='close'){state.pending=null;closeModal();}if(action==='demo-login'){button.disabled=true;await signedIn(await post('/auth/demo',{role:button.dataset.role}),button.dataset.role==='admin');}
 if(action==='logout'){await post('/auth/logout');state.user=null;state.saved.clear();navigate('/');}
 if(action==='save')await save(button.dataset.id);if(action==='sector'){state.sector=button.dataset.sector;$$('.home-search .switch button').forEach(b=>{b.classList.toggle('selected',b.dataset.sector===state.sector);b.setAttribute('aria-pressed',String(b.dataset.sector===state.sector));});}
 if(action==='filters'){const q=new URLSearchParams(location.search);q.get('filters')==='1'?q.delete('filters'):q.set('filters','1');navigate('/properties?'+q,{scroll:false});}
 if(action==='refresh')await render({scroll:false});if(action==='enquire')enquiry();if(action==='inspect')inspect();if(action==='read-more'){const block=button.previousElementSibling;const collapsed=block.classList.toggle('is-collapsed');button.innerHTML=`${collapsed?'Read more':'Read less'} ${icon(collapsed?'down':'up')}`;}if(action==='gallery')gallery(Number(button.dataset.index||0));if(action==='gallery-next')gallery((state.gallery+1)%state.currentProperty.media.length);if(action==='gallery-prev')gallery((state.gallery+state.currentProperty.media.length-1)%state.currentProperty.media.length);
 if(action.startsWith('media-')){const i=Number(button.dataset.index),arr=state.editor.media;if(action==='media-remove')arr.splice(i,1);if(action==='media-up'&&i>0)[arr[i-1],arr[i]]=[arr[i],arr[i-1]];if(action==='media-down'&&i<arr.length-1)[arr[i+1],arr[i]]=[arr[i],arr[i+1]];$('#media-editor').innerHTML=mediaRows();}
 if(action==='new-slot')await slotModal();if(action==='inspection-status'){const id=button.dataset.id,status=button.dataset.status;if(status==='cancelled'){modal('Cancel this inspection?',`<p>The request will remain in the account as cancelled.</p><form data-form="cancel-inspection" data-id="${id}"><label>Reason (optional)<input name="reason" maxlength="300"></label><div class="form-error" role="alert"></div><button class="btn">Cancel inspection</button></form>`);}else if(status==='confirmed'&&!button.dataset.slot){const{slots}=await api('/properties/'+button.dataset.property);modal('Choose a confirmed time.',`<form data-form="confirm-inspection" data-id="${id}"><label>Available inspection time<select name="slot_id" required>${options(slots.map(s=>[s.id,date(s.starts_at)]),'','Choose a time')}</select></label><p class="small">Australia/Sydney. Add an inspection time first if no slots are available.</p><div class="form-error" role="alert"></div><button class="btn">Confirm inspection</button></form>`);}else{await api('/inspections/'+id,{method:'PATCH',body:{status}});toast('Inspection '+status+'.');await render({scroll:false});}}
 }catch(e){toast(e.message);button.disabled=false;}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.mediaAlt!==undefined)state.editor.media[Number(el.dataset.mediaAlt)].alt=el.value;if(el.name==='body'){if(el.closest('[data-form="reply"]'))sessionStorage.setItem('draft-'+state.currentThread.id,el.value);if(el.closest('[data-form="enquiry"]'))sessionStorage.setItem('enquiry-'+state.currentProperty.id,el.value);}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.change==='sort'){const q=new URLSearchParams(location.search);q.set('sort',el.value);navigate('/properties?'+q,{scroll:false});}if(el.dataset.change==='days')navigate('/admin?days='+el.value,{scroll:false});if(el.dataset.change==='inbox-filter')navigate('/admin/conversations?filter='+el.value,{scroll:false});if(el.dataset.change==='editor-sector'){const list=el.value==='commercial'?commercialTypes:residentialTypes;$('#property-type').innerHTML=options(list,list[0][0]);}if(el.dataset.change==='upload'){el.disabled=true;for(const file of el.files){if(file.size>5*1024*1024)throw new Error('Each image must be under 5 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const result=await post('/admin/upload',{data});state.editor.media.push({url:result.url,alt:file.name.replace(/\.[^.]+$/,'').replaceAll('-',' ')});}$('#media-editor').innerHTML=mediaRows();toast('Photographs uploaded. Save the listing to keep their order.');el.value='';}}catch(e){toast(e.message);}finally{el.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const type=form.dataset.form;const data=Object.fromEntries(new FormData(form));const submit=$('button[type="submit"],button:not([type])',form);const error=$('.form-error',form);if(error)error.textContent='';if(submit)submit.disabled=true;try{
 if(type==='home-search')return navigate('/properties?'+new URLSearchParams({sector:state.sector,...(data.location.trim()?{location:data.location.trim()}:{})}));
 if(type==='search'||type==='filters'){const q=new URLSearchParams(location.search);if(type==='filters')for(const key of ['type','beds','baths','tenancy','min_floor','min','max','pending'])q.delete(key);for(const[k,v]of Object.entries(data)){v?q.set(k,v):q.delete(k);}if(data.min&&data.max&&Number(data.min)>Number(data.max))throw new Error('Minimum price must not exceed maximum price.');return navigate('/properties?'+q,{scroll:false});}
 if(type==='auth')await signedIn(await post('/auth/'+state.authMode,data));
 if(type==='profile'){state.user=(await api('/profile',{method:'PATCH',body:data})).user;renderHeader();mountExperience();toast('Your name has been updated.');}
 if(type==='enquiry'){form.dataset.key ||= crypto.randomUUID();const result=await post('/conversations',{property_id:state.currentProperty.id,body:data.body,client_key:form.dataset.key});sessionStorage.removeItem('enquiry-'+state.currentProperty.id);closeModal();navigate('/account/messages/'+result.id);toast('Your message is saved.');}
 if(type==='reply'){form.dataset.key ||= crypto.randomUUID();await post(`/conversations/${state.currentThread.id}/messages`,{body:data.body,client_key:form.dataset.key});sessionStorage.removeItem('draft-'+state.currentThread.id);await render({scroll:false});toast('Message saved.');}
 if(type==='note'){await post(`/conversations/${state.currentThread.id}/notes`,{body:data.body});await render({scroll:false});toast('Private note added.');}
 if(type==='thread-workflow'){await api('/conversations/'+state.currentThread.id,{method:'PATCH',body:{...data,blocked:data.blocked==='on',due_at:data.due_at?new Date(data.due_at).toISOString():''}});toast('Next steps saved.');}
 if(type==='inspection'){await post('/inspections',{...data,property_id:state.currentProperty.id});closeModal();navigate('/account/inspections');toast('Inspection requested. The team still needs to confirm.');}
 if(type==='cancel-inspection'||type==='confirm-inspection'){await api('/inspections/'+form.dataset.id,{method:'PATCH',body:{...data,status:type==='cancel-inspection'?'cancelled':'confirmed'}});closeModal();await render({scroll:false});toast('Inspection updated.');}
 if(type==='new-slot'){await post('/admin/slots',{...data,capacity:Number(data.capacity),starts_at:new Date(data.starts_at).toISOString()});closeModal();toast('Inspection time added.');}
 if(type==='content'){await api('/content',{method:'PATCH',body:data});state.content=await api('/content');toast('Homepage copy updated.');}
 if(type==='team'){await api('/admin/team',{method:'PATCH',body:{...data,active:data.active==='on'}});toast('Access updated. Existing sessions ended.');}
 if(type==='editor'){const highlights=data.highlights.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,6);const details=data.details.split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{const i=line.indexOf(':');return i===-1?[line,'']:[line.slice(0,i).trim(),line.slice(i+1).trim()];}).slice(0,30);const payload={...state.editor,...data,price_minor:Math.round(Number(data.price)*100),bedrooms:Number(data.bedrooms),bathrooms:Number(data.bathrooms),parking:Number(data.parking),floor_area:Number(data.floor_area)||0,land_area:Number(data.land_area)||0,featured:data.featured==='on'?1:0,is_demo:data.real_listing==='on'?0:1,features:data.features.split('\n').map(s=>s.trim()).filter(Boolean),highlights,details};delete payload.real_listing;delete payload.mode;const result=await api('/admin/properties',{method:payload.id?'PATCH':'POST',body:payload});toast('Listing saved.');navigate('/admin/properties/'+result.property.id+'/edit',{scroll:false});}
 }catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
window.addEventListener('popstate',()=>render());
document.addEventListener('keydown',e=>{if($('#modal').open&&$('#modal').classList.contains('gallery-dialog')){if(e.key==='ArrowRight')gallery((state.gallery+1)%state.currentProperty.media.length);if(e.key==='ArrowLeft')gallery((state.gallery+state.currentProperty.media.length-1)%state.currentProperty.media.length);}});
$('#modal').addEventListener('cancel',()=>{state.pending=null;});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
async function boot(){try{const[session,content]=await Promise.all([api('/session'),api('/content')]);Object.assign(state,session,{content});if(state.user)state.saved=new Set((await api('/saves')).ids);await render();}catch(e){$('#main').innerHTML=`<div class="wrap section"><div class="error">${esc(e.message)} Start the Porli server and reload.</div></div>`;}}
boot();
